const fs = require('fs');
const path = require('path');

const dir = __dirname;
const config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf8'));

const defaults = { port: 3000, host: '127.0.0.1' };
const out = { ...defaults, ...config };

fs.writeFileSync(path.join(dir, 'config.out.json'), JSON.stringify(out, null, 2) + '\n');
console.log('wrote config.out.json:', out);

